 client.channel.close();server.send_signal(signal.SIGINT);server.wait(timeout=max(.1,180-(time.monotonic()-stop)));assert server.returncode==0
 print('RESTORE_ORDERED_STOP_PASS '+json.dumps({'monotonic':time.monotonic(),'model_exit':model.returncode,'server_exit':server.returncode}),flush=True)
