   try:model.wait(timeout=5)
   except subprocess.TimeoutExpired:model.kill();model.wait(timeout=5)
  except BaseException as cleanup_error:print('RESTORE_FAILED_MODEL_REAP '+type(cleanup_error).__name__,flush=True)
 # PID1 must remain alive while authenticated CID guard owns aggregate cleanup.
 if not server_reaped:
  print('RESTORE_GUARD_REQUIRED '+json.dumps({'error_type':type(primary_error).__name__,'error':str(primary_error),'reason':'Store could not be reaped; original failure retained; aggregate guard required, not IPCsafe'}),flush=True)
  while True:time.sleep(1)
 raise

